BEGIN TRANSACTION;
CREATE TABLE "academics_course" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "code" varchar(20) NOT NULL UNIQUE, "name" varchar(180) NOT NULL, "credit_hours" decimal NOT NULL, "semester" varchar(20) NOT NULL, "instructor_name" varchar(120) NOT NULL, "status" varchar(20) NOT NULL, "department_id" bigint NOT NULL REFERENCES "academics_department" ("id") DEFERRABLE INITIALLY DEFERRED, "instructor_id" bigint NULL REFERENCES "academics_faculty" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "academics_department" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL UNIQUE, "code" varchar(20) NOT NULL UNIQUE, "is_active" bool NOT NULL);
CREATE TABLE "academics_faculty" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "employee_id" varchar(30) NOT NULL UNIQUE, "full_name" varchar(180) NOT NULL, "email" varchar(254) NOT NULL, "title" varchar(80) NOT NULL, "is_active" bool NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "department_id" bigint NULL REFERENCES "academics_department" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL UNIQUE REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "academics_program" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL, "code" varchar(20) NOT NULL UNIQUE, "duration_semesters" smallint unsigned NOT NULL CHECK ("duration_semesters" >= 0), "is_active" bool NOT NULL, "department_id" bigint NOT NULL REFERENCES "academics_department" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "role" varchar(20) NOT NULL, "email_verified" bool NOT NULL, "must_change_password" bool NOT NULL);
CREATE TABLE "accounts_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "accounts_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "attendance_attendancerecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "student_id" varchar(30) NOT NULL, "status" varchar(20) NOT NULL, "remarks" varchar(255) NOT NULL, "session_id" bigint NOT NULL REFERENCES "attendance_attendancesession" ("id") DEFERRABLE INITIALLY DEFERRED, "enrollment_id" bigint NULL REFERENCES "attendance_enrollment" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "attendance_attendancesession" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "session_date" date NOT NULL, "semester" varchar(20) NOT NULL, "instructor_name" varchar(120) NOT NULL, "time_slot" varchar(30) NOT NULL, "created_at" datetime NOT NULL, "course_id" bigint NOT NULL REFERENCES "academics_course" ("id") DEFERRABLE INITIALLY DEFERRED, "department_id" bigint NULL REFERENCES "academics_department" ("id") DEFERRABLE INITIALLY DEFERRED, "instructor_id" bigint NULL REFERENCES "academics_faculty" ("id") DEFERRABLE INITIALLY DEFERRED, "program_id" bigint NULL REFERENCES "academics_program" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "attendance_enrollment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "student_id" varchar(30) NOT NULL, "enrolled_at" datetime NOT NULL, "course_id" bigint NOT NULL REFERENCES "academics_course" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "audits_auditlog" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "action" varchar(80) NOT NULL, "object_modified" varchar(255) NOT NULL, "old_value" text NOT NULL, "new_value" text NOT NULL, "ip_address" char(39) NULL, "user_agent" text NOT NULL, "timestamp" datetime NOT NULL, "user_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "documents_document" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(180) NOT NULL, "category" varchar(30) NOT NULL, "file" varchar(100) NOT NULL, "is_public" bool NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "fees_feestructure" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "fee_type" varchar(30) NOT NULL, "amount" decimal NOT NULL, "academic_year" varchar(20) NOT NULL, "semester" varchar(20) NOT NULL);
CREATE TABLE "fees_payment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "student_id_text" varchar(30) NOT NULL, "amount_paid" decimal NOT NULL, "paid_on" date NOT NULL, "reference" varchar(60) NOT NULL, "fee_structure_id" bigint NOT NULL REFERENCES "fees_feestructure" ("id") DEFERRABLE INITIALLY DEFERRED, "student_id" bigint NULL REFERENCES "students_student" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "gradebook_exam" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(150) NOT NULL, "course_code" varchar(20) NOT NULL, "assessment_type" varchar(20) NOT NULL, "total_marks" integer unsigned NOT NULL CHECK ("total_marks" >= 0), "exam_date" date NOT NULL, "is_published" bool NOT NULL);
CREATE TABLE "gradebook_graderecord" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "student_id" varchar(30) NOT NULL, "marks_obtained" decimal NOT NULL, "letter_grade" varchar(4) NOT NULL, "grade_points" decimal NOT NULL, "exam_id" bigint NOT NULL REFERENCES "gradebook_exam" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "helpdesk_ticket" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "student_id_text" varchar(30) NOT NULL, "subject" varchar(180) NOT NULL, "description" text NOT NULL, "category" varchar(20) NOT NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "student_id" bigint NULL REFERENCES "students_student" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "helpdesk_ticketreply" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "author_name_text" varchar(120) NOT NULL, "message" text NOT NULL, "created_at" datetime NOT NULL, "author_id" bigint NULL REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED, "ticket_id" bigint NOT NULL REFERENCES "helpdesk_ticket" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "notifications_center_announcement" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(180) NOT NULL, "description" text NOT NULL, "publish_date" date NOT NULL, "expiry_date" date NULL, "department_name" varchar(100) NOT NULL, "semester" varchar(20) NOT NULL, "is_active" bool NOT NULL, "department_id" bigint NULL REFERENCES "academics_department" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "notifications_center_notification" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "student_id_text" varchar(30) NOT NULL, "title" varchar(180) NOT NULL, "message" text NOT NULL, "is_read" bool NOT NULL, "created_at" datetime NOT NULL, "student_id" bigint NULL REFERENCES "students_student" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "registration_courseoffering" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "course_code_text" varchar(20) NOT NULL, "semester" varchar(20) NOT NULL, "capacity" integer unsigned NOT NULL CHECK ("capacity" >= 0), "course_id" bigint NULL REFERENCES "academics_course" ("id") DEFERRABLE INITIALLY DEFERRED, "registration_window_id" bigint NOT NULL REFERENCES "registration_registrationwindow" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "registration_courseregistration" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "student_id_text" varchar(30) NOT NULL, "status" varchar(20) NOT NULL, "registered_at" datetime NOT NULL, "offering_id" bigint NOT NULL REFERENCES "registration_courseoffering" ("id") DEFERRABLE INITIALLY DEFERRED, "student_id" bigint NULL REFERENCES "students_student" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "registration_registrationwindow" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL, "starts_at" datetime NOT NULL, "ends_at" datetime NOT NULL, "is_active" bool NOT NULL);
CREATE TABLE "students_address" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "address_type" varchar(20) NOT NULL, "address_line_1" varchar(255) NOT NULL, "address_line_2" varchar(255) NOT NULL, "city" varchar(120) NOT NULL, "state" varchar(120) NOT NULL, "postal_code" varchar(20) NOT NULL, "country" varchar(100) NOT NULL, "student_id" bigint NOT NULL REFERENCES "students_student" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "students_contactinformation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "primary_email" varchar(254) NOT NULL UNIQUE, "secondary_email" varchar(254) NOT NULL, "mobile_number" varchar(20) NOT NULL, "alternate_mobile_number" varchar(20) NOT NULL, "student_id" bigint NOT NULL UNIQUE REFERENCES "students_student" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "students_emergencycontact" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "contact_name" varchar(150) NOT NULL, "relationship" varchar(80) NOT NULL, "mobile_number" varchar(20) NOT NULL, "email_address" varchar(254) NOT NULL, "student_id" bigint NOT NULL UNIQUE REFERENCES "students_student" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "students_student" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "student_id" varchar(30) NOT NULL UNIQUE, "first_name" varchar(100) NOT NULL, "middle_name" varchar(100) NOT NULL, "last_name" varchar(100) NOT NULL, "date_of_birth" date NULL, "gender" varchar(10) NOT NULL, "nationality" varchar(100) NOT NULL, "blood_group" varchar(5) NOT NULL, "profile_photo" varchar(100) NOT NULL, "registration_number" varchar(50) NOT NULL UNIQUE, "academic_year" varchar(20) NOT NULL, "semester" varchar(20) NOT NULL, "enrollment_date" date NOT NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "department_id" bigint NULL REFERENCES "academics_department" ("id") DEFERRABLE INITIALLY DEFERRED, "program_id" bigint NULL REFERENCES "academics_program" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL UNIQUE REFERENCES "accounts_user" ("id") DEFERRABLE INITIALLY DEFERRED);
